package com.meshcrossway.android;
import java.util.*;
import static com.meshcrossway.android.MeshData.*;

/** Regression fixtures use real protobuf envelopes, not UI label order or optimistic cache values. */
public final class MtSettingsTest {
    static long time=100;
    static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);}
    static void rejects(Runnable r){try{r.run();throw new AssertionError("Expected validation error");}catch(IllegalArgumentException expected){}}
    static byte[] wrap(int tag,byte[] bytes){return new Wire.Out().bytes(tag,bytes).array();}
    static ProtocolClient fresh(){ProtocolClient c=ProtocolClientTest.mt(new ProtocolClientTest.Events());c.firmware="2.8.1";c.admin.clock=time;return c;}
    static long take(ProtocolClient c){ProtocolClient.Command command=c.next(time++);check(command!=null,"command exists");List<Wire.F> packet=Wire.fields(Wire.bytes(Wire.fields(command.data),1));long id=Wire.number(packet,6,0);c.written(time++);c.next(time++);return id;}
    static void response(ProtocolClient c,long id,int kind,byte[] body){byte[] admin=new Wire.Out().bytes(kind,body).bytes(101,new byte[]{1,2,3}).array();packet(c,100,100,6,id,admin);}
    static void packet(ProtocolClient c,long from,long to,int port,long id,byte[] body){byte[] data=new Wire.Out().scalar(1,port).fixed(6,id).bytes(2,body).array();c.receive(wrap(2,new Wire.Out().fixed(1,from).fixed(2,to).bytes(4,data).array()),time++);}
    static void ack(ProtocolClient c,long id,int code){packet(c,100,100,5,id,new Wire.Out().scalar(3,code).array());}
    public static void main(String[] args){
        check(MtLora.PRESETS[3].label.equals("MEDIUM SLOW")&&MtLora.PRESETS[3].value==3,"medium slow wire enum");
        check(MtLora.PRESETS[4].label.equals("MEDIUM FAST")&&MtLora.PRESETS[5].label.equals("SHORT SLOW")&&MtLora.PRESETS[6].label.equals("SHORT FAST"),"preset labels agree with numeric IDs");
        check(MtLora.presetName(99).contains("99"),"unknown preset is not clamped");check(MtLora.atLeast("2.8.1.abcd",2,8,0)&&!MtLora.atLeast("2.7.19",2,7,20)&&!MtLora.atLeast("unknown",2,0,0),"version gates");
        ProtocolClient c=fresh();rejects(()->c.setMtOwnerName(false,"Before read"));
        c.requestMtConfig(0);long request=take(c);byte[] config=wrap(1,Wire.EMPTY);
        packet(c,200,100,6,request,new Wire.Out().bytes(6,config).bytes(101,new byte[]{9}).array());check(!c.mtConfigLoaded(0)&&c.admin.key.length==0,"foreign node cannot change local admin state");
        response(c,request+999,6,config);check(!c.mtConfigLoaded(0),"unsolicited response ignored");response(c,request,6,config);check(c.mtConfigLoaded(0)&&c.mtConfig(0).length==0,"empty default config loaded");
        c.setMtConfigField(0,1,1);check(c.mtConfig(0).length==0,"save does not optimistically change cache");long write=take(c);ack(c,write,1);check(c.admin.edit==null&&!c.admin.error.isEmpty()&&c.mtConfig(0).length==0,"negative admin ACK preserves values");
        c.setMtConfigField(0,1,1);write=take(c);ack(c,write,0);long readback=take(c);response(c,readback,6,wrap(1,new Wire.Out().scalar(1,1).array()));check(c.admin.edit==null&&c.admin.status.startsWith("Saved")&&Wire.number(Wire.fields(c.mtConfig(0)),1,0)==1,"ACK then correlated readback confirms value");
        c.requestMtModule(0);request=take(c);response(c,request,8,wrap(1,Wire.EMPTY));check(c.mtModuleLoaded(0)&&c.mtModule(0).length==0,"empty module response field8 decoded");
        c.admin.clock+=240001;c.setMtModuleField(0,1,1);ProtocolClient.Command keyCommand=c.next(time=c.admin.clock+1);check(keyCommand!=null,"key refresh command");List<Wire.F> pk=Wire.fields(Wire.bytes(Wire.fields(keyCommand.data),1));byte[] ad=Wire.bytes(Wire.fields(Wire.bytes(pk,4)),2);check(Wire.field(Wire.fields(ad),12)!=null,"expired key refreshes using metadata GET");check(c.admin.edit.writeId==0,"write deferred until new key");c.written(time++);c.next(time++);request=Wire.number(pk,6,0);response(c,request,13,new Wire.Out().bytes(1,"2.8.1".getBytes()).array());write=take(c);check(c.admin.edit.writeId==write,"write resumes after key refresh");
        MtAdmin.Edit recovery=c.admin.edit;ProtocolClient reconnected=fresh();reconnected.admin.restore(recovery);reconnected.admin.clock=time;reconnected.admin.ready();readback=take(reconnected);response(reconnected,readback,8,wrap(1,new Wire.Out().scalar(1,1).array()));check(reconnected.admin.edit==null,"reconnect verifies pending save without resending SET");
        ProtocolClient channels=fresh();byte[] unnamed=new Wire.Out().scalar(1,0).bytes(2,new Wire.Out().bytes(2,new byte[]{1}).array()).scalar(3,1).array();channels.receive(wrap(10,unnamed),time++);String identity=channels.channels.get(0).identity;channels.requestMtOwner();request=take(channels);response(channels,request,4,new Wire.Out().bytes(2,"Original".getBytes()).array());channels.setMtChannelName(0,"NewName");write=take(channels);ack(channels,write,0);readback=take(channels);byte[] renamed=Wire.replaceBytes(unnamed,2,new Wire.Out().bytes(2,new byte[]{1}).bytes(3,"NewName".getBytes()).array());response(channels,readback,2,renamed);check(channels.channels.get(0).name.equals("NewName")&&channels.channels.get(0).identity.equals(identity),"unnamed channel rename inserts field and keeps key identity");rejects(()->channels.setMtChannelName(0,"abcdefghijkl"));channels.requestMtModule(13);request=take(channels);response(channels,request,8,wrap(14,Wire.EMPTY));check(channels.mtModuleLoaded(13),"status module loaded before limits test");rejects(()->channels.setMtStatus("😀".repeat(21)));rejects(()->channels.setMtOwnerName(false,"é".repeat(13)));
        byte[] lora=channels.mtConfig(5);rejects(()->channels.setMtConfigFloat(5,14,Double.NaN));rejects(()->channels.setMtConfigFloat(5,14,Double.POSITIVE_INFINITY));
        final byte[] invalidManual=Wire.replace(lora,1,0);rejects(()->MtLora.validate(invalidManual,channels));byte[] manual=Wire.replace(Wire.replace(Wire.replace(invalidManual,3,250),4,11),5,5);MtLora.validate(manual,channels);rejects(()->MtLora.validate(Wire.replace(manual,3,100),channels));check(MtLora.manualBandwidth(15,1)==15.625,"fractional bandwidth used for slot validation");
        Target target=Target.channel(channels.channels.get(0)).reply(123,false);Message outgoing=channels.send(target,"reply",600,time++);ProtocolClient.Command cmd=channels.next(time++);List<Wire.F> d=Wire.fields(Wire.bytes(Wire.fields(Wire.bytes(Wire.fields(cmd.data),1)),4));check(Wire.number(d,7,0)==123&&outgoing.rx.replyId==123,"structured reply wire and persisted model");channels.written(time++);channels.next(time++);
        byte[] reaction=new Wire.Out().scalar(1,1).bytes(2,"👍".getBytes()).fixed(7,600).fixed(8,1).array();channels.receive(wrap(2,new Wire.Out().fixed(1,200).fixed(2,0xffffffffL).fixed(6,601).bytes(4,reaction).array()),time++); // foreign/local radio scopes remain distinct
        ProtocolClient ham=fresh();ham.requestMtOwner();long ownerRequest=take(ham);response(ham,ownerRequest,4,new Wire.Out().bytes(2,"Old name".getBytes()).bytes(3,"AB".getBytes()).array());ham.setMtHam("K0ABC","Test");ProtocolClient.Command hamCommand=ham.next(time++);List<Wire.F> hamPacket=Wire.fields(Wire.bytes(Wire.fields(hamCommand.data),1));byte[] hamAdmin=Wire.bytes(Wire.fields(Wire.bytes(hamPacket,4)),2);check(Wire.field(Wire.fields(hamAdmin),18)!=null&&Wire.field(Wire.fields(hamAdmin),32)==null,"Ham onboarding uses set_ham_mode rather than set_owner");byte[] parameters=Wire.bytes(Wire.fields(hamAdmin),18);check(Wire.utf8(Wire.bytes(Wire.fields(parameters),1)).equals("K0ABC")&&Wire.field(Wire.fields(parameters),2)!=null&&Wire.field(Wire.fields(parameters),3)!=null,"Ham params preserve callsign and explicit power/frequency");
        ProtocolClient metrics=fresh();byte[] dm=new Wire.Out().scalar(1,91).fixed(2,Float.floatToIntBits(4.08f)).array(),env=new Wire.Out().fixed(1,Float.floatToIntBits(55f)).array();packet(metrics,200,100,67,0,new Wire.Out().fixed(1,1700000000L).bytes(2,dm).bytes(3,env).array());Node node=metrics.nodes.get("200");check(node.battery==91&&node.metrics.get("Device").contains("4.080")&&node.metrics.get("Environment").contains("55.000")&&node.metricHistory.size()==2,"telemetry decoded with named fields and samples");packet(metrics,200,100,36,0,new Wire.Out().bytes(1,"Available".getBytes()).array());check(metrics.nodes.get("200").status.equals("Available"),"node status app");
        byte[] eu=Wire.replace(Wire.replace(Wire.replace(channels.mtConfig(5),1,1),7,3),2,0);rejects(()->MtLora.validate(Wire.replace(eu,11,2),channels));check(!MtLora.selectable(channels,3,9),"wide preset excluded from narrow region");
        ProtocolClient timeouts=fresh();timeouts.requestMtConfig(0);take(timeouts);timeouts.admin.tick(time+30001);int pending=timeouts.commands.size();timeouts.requestMtConfig(0);check(timeouts.commands.size()==pending&&!timeouts.admin.error.isEmpty(),"failed read does not loop from page refresh");timeouts.admin.retryReads();timeouts.requestMtConfig(0);check(!timeouts.commands.isEmpty(),"explicit refresh retries read");
        ProtocolClient licensed=fresh();licensed.mtOwnerLoaded=true;licensed.mtOwner=new Wire.Out().scalar(6,1).array();Message licensedDm=licensed.send(Target.node(licensed.nodes.get("200")),"licensed sender",801,time++);ProtocolClient.Command licensedCommand=licensed.next(time++);List<Wire.F> licensedPacket=Wire.fields(Wire.bytes(Wire.fields(licensedCommand.data),1));check(Wire.field(licensedPacket,16)==null&&Wire.field(licensedPacket,17)==null,"licensed sender does not request PKI encryption");licensed.written(time++);licensed.next(time++);licensed.mtOwner=new Wire.Out().scalar(6,0).array();licensed.nodes.get("200").licensed=true;licensed.nodes.get("200").key="";licensed.send(Target.node(licensed.nodes.get("200")),"licensed recipient",802,time++);licensedCommand=licensed.next(time++);licensedPacket=Wire.fields(Wire.bytes(Wire.fields(licensedCommand.data),1));check(Wire.field(licensedPacket,17)==null,"licensed recipient does not require a PKI key");
        ProtocolClient syncedLicense=fresh();syncedLicense.receive(wrap(4,new Wire.Out().scalar(1,100).bytes(2,new Wire.Out().scalar(6,1).array()).array()),time++);check(!syncedLicense.mtOwnerLoaded&&syncedLicense.mtHam(),"initial synchronization supplies own licensed state before User settings");
        ProtocolClient noAck=fresh();noAck.requestMtConfig(0);request=take(noAck);response(noAck,request,6,wrap(1,Wire.EMPTY));
        noAck.setMtConfigField(0,1,1);write=take(noAck);time=noAck.admin.clock+2001;
        readback=take(noAck);response(noAck,readback,6,wrap(1,new Wire.Out().scalar(1,1).array()));
        check(noAck.admin.edit==null&&noAck.admin.status.startsWith("Saved"),"save automatically verified without routing ACK");
        ProtocolClient mismatch=fresh();mismatch.requestMtConfig(0);request=take(mismatch);response(mismatch,request,6,wrap(1,Wire.EMPTY));
        mismatch.setMtConfigField(0,1,1);write=take(mismatch);ack(mismatch,write,0);readback=take(mismatch);
        response(mismatch,readback,6,wrap(1,Wire.EMPTY));check(mismatch.admin.edit==null&&!mismatch.admin.error.isEmpty(),"mismatch unlocks controls and keeps clear failure");
        check(mismatch.mtConfig(0).length==0,"mismatch keeps actual radio values");mismatch.setMtConfigField(0,1,2);check(mismatch.admin.edit!=null,"next edit requires no manual discard after mismatch");
        ProtocolClient stale=fresh();stale.requestMtConfig(0);request=take(stale);response(stale,request,6,wrap(1,Wire.EMPTY));
        stale.requestMtConfig(0);long oldRead=take(stale);stale.setMtConfigField(0,1,1);write=take(stale);
        response(stale,oldRead,6,wrap(1,Wire.EMPTY));check(stale.admin.edit!=null,"pre-write read cannot reject pending save");ack(stale,write,0);readback=take(stale);
        response(stale,readback,6,wrap(1,new Wire.Out().scalar(1,1).array()));check(stale.admin.edit==null&&stale.admin.error.isEmpty(),"new correlated read confirms pending save");
        ProtocolClient lost=fresh();lost.requestMtConfig(0);request=take(lost);response(lost,request,6,wrap(1,Wire.EMPTY));lost.setMtConfigField(0,1,1);write=take(lost);ack(lost,write,0);take(lost);
        time+=30001;lost.admin.tick(time);check(lost.admin.edit!=null&&lost.admin.edit.deadline==Long.MAX_VALUE,"missing readback stops progress with recoverable state");lost.admin.verify();readback=take(lost);
        response(lost,readback,6,wrap(1,new Wire.Out().scalar(1,1).array()));check(lost.admin.edit==null&&lost.admin.error.isEmpty(),"checking again clears failed read guard and confirms without repeating SET");
        ProtocolClient normalized=fresh();check(MtLora.currentPreset(normalized).equals("Manual LoRa"),"Home uses synchronized mode, not assumed LONG FAST");
        normalized.requestMtConfig(5);request=take(normalized);byte[] initial=new Wire.Out().scalar(1,1).scalar(2,4).scalar(5,5).scalar(7,1).scalar(9,1).array();response(normalized,request,6,wrap(6,initial));
        byte[] desired=Wire.replace(Wire.replace(initial,2,0),5,0);normalized.setMtConfig(5,desired);write=take(normalized);ack(normalized,write,0);readback=take(normalized);
        response(normalized,readback,6,wrap(6,Wire.replace(desired,5,5)));check(normalized.admin.edit==null&&normalized.admin.error.isEmpty()&&normalized.admin.status.contains("LONG FAST"),"firmware zero-to-five normalization confirms preset and names it");
        check(MtLora.currentPreset(normalized).equals("LONG FAST"),"Home preset comes from confirmed readback");MtLora.validate(normalized.mtConfig(5),normalized);
        byte[] slow=Wire.replace(desired,2,1);check(MtLora.codingMatches(Wire.replace(slow,5,5),slow),"slow preset stored CR5 still uses preset CR8");
        check(!MtLora.codingMatches(Wire.replace(desired,2,4),desired),"a different preset is never equivalent");
        check(!MtLora.codingMatches(Wire.replace(desired,1,0),desired),"manual mode is never equivalent to preset mode");
        byte[] override=Wire.replace(desired,5,6);check(!MtLora.codingMatches(Wire.replace(override,5,5),override),"custom CR override cannot silently fall back to default");
        check(!MtLora.codingMatches(Wire.replace(desired,5,9),desired),"invalid coding rate cannot confirm default");
        check(MtLora.codingSelection(0,5)==0&&MtLora.codingSelection(0,6)==6&&MtLora.codingSelection(1,5)==0,"coding selector recognizes stored preset defaults");
        normalized.setMtConfig(5,Wire.replace(normalized.mtConfig(5),8,4));write=take(normalized);ack(normalized,write,0);readback=take(normalized);response(normalized,readback,6,wrap(6,normalized.mtConfig(5)));check(!normalized.admin.error.isEmpty(),"unapplied non-coding setting is still rejected");
        normalized.setMtConfig(5,Wire.replace(normalized.mtConfig(5),2,4));write=take(normalized);ack(normalized,write,0);readback=take(normalized);response(normalized,readback,6,wrap(6,normalized.mtConfig(5)));check(!normalized.admin.error.isEmpty(),"a requested preset that did not change remains unconfirmed");
        ProtocolClient unknown=new ProtocolClient(RadioProfile.MESHTASTIC,42,new ProtocolClientTest.Events());check(MtLora.currentPreset(unknown).equals("Reading preset…"),"unread preset is never invented");
        System.out.println("Meshtastic regressions: enums, empty defaults, correlated admin GET/ACK/readback, expiry, reboot recovery, modules, channels, limits and replies passed");
    }
}
